import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"UI Framework Candidates","description":"","frontmatter":{},"headers":[],"relativePath":"development/ui-framework-candidates.md","filePath":"development/ui-framework-candidates.md","lastUpdated":1780254295000}'),r={name:"development/ui-framework-candidates.md"};function n(s,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="ui-framework-candidates" tabindex="-1">UI Framework Candidates <a class="header-anchor" href="#ui-framework-candidates" aria-label="Permalink to &quot;UI Framework Candidates&quot;">​</a></h1><p>Soma (the Tauri V2 desktop app, including the planned Tapia typing-practice surface) currently uses React 19, Tailwind CSS v4, DaisyUI, Floating UI, Motion, and a shared @soma/ui package. That works, but DaisyUI is carrying too much visual opinion into an app that wants a dense, native-feeling desktop surface.</p><h2 id="what-we-need" tabindex="-1">What We Need <a class="header-anchor" href="#what-we-need" aria-label="Permalink to &quot;What We Need&quot;">​</a></h2><ul><li>Headless or lightly styled primitives so <code>@soma/ui</code> remains the design-system boundary.</li><li>Strong accessibility defaults for menus, dialogs, comboboxes, tabs, toolbars, trees, and keyboard navigation.</li><li>Tailwind-compatible styling with no mandatory CSS-in-JS runtime.</li><li>React 19 compatibility and good behavior inside the Tauri WebView (WKWebView on macOS, WebKitGTK on Linux).</li><li>Composable APIs that can support Soma&#39;s workspace shell and the planned <code>/practice</code> route&#39;s focused interaction states without fighting Motion.</li></ul><h2 id="leading-candidate-base-ui" tabindex="-1">Leading Candidate: Base UI <a class="header-anchor" href="#leading-candidate-base-ui" aria-label="Permalink to &quot;Leading Candidate: Base UI&quot;">​</a></h2><p><a href="https://base-ui.com/react/overview/about" target="_blank" rel="noreferrer">Base UI</a> is the best first candidate to prototype. It is an unstyled React component library focused on accessibility, performance, and developer experience, and its docs explicitly support Tailwind, CSS modules, plain CSS, and CSS-in-JS.</p><p>Why it fits Soma:</p><ul><li>It lets us keep Tailwind v4 and <code>@soma/ui</code> as the visible design layer.</li><li>It avoids DaisyUI&#39;s global class vocabulary and theme assumptions.</li><li>It gives us accessible primitive behavior without forcing a product look.</li><li>It comes from maintainers with Radix, Floating UI, Material UI, and Base UI lineage, which matters for the exact overlay/menu/focus problems desktop apps tend to hit.</li></ul><p>Recommended experiment:</p><ol><li>Pick one overlay-heavy component, probably command palette or context menu.</li><li>Rebuild it behind the same <code>@soma/ui</code> export using Base UI primitives.</li><li>Compare keyboard behavior, focus restore, animation hooks, bundle impact, and styling friction.</li><li>Keep DaisyUI available during the experiment, but avoid new DaisyUI-only APIs.</li></ol><h2 id="other-candidates" tabindex="-1">Other Candidates <a class="header-anchor" href="#other-candidates" aria-label="Permalink to &quot;Other Candidates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Candidate</th><th>Fit</th><th>Concern</th></tr></thead><tbody><tr><td><a href="https://react-spectrum.adobe.com/react-aria/components.html" target="_blank" rel="noreferrer">React Aria Components</a></td><td>Best accessibility depth and broad component coverage.</td><td>API and styling model may feel heavier than we need for a custom desktop shell.</td></tr><tr><td><a href="https://ark-ui.com/react/docs/overview/introduction" target="_blank" rel="noreferrer">Ark UI</a></td><td>Headless, accessible, broad component set, and a state-machine flavor that could pair well with the typing-practice surface.</td><td>Multi-framework abstraction may add concepts we do not need in a React-only app.</td></tr><tr><td><a href="https://www.radix-ui.com/primitives/docs/overview/introduction" target="_blank" rel="noreferrer">Radix Primitives</a></td><td>Mature low-level primitives, familiar ecosystem, good fit for shadcn-style wrappers.</td><td>Base UI looks like the fresher direction for this exact unstyled React primitive layer.</td></tr><tr><td><a href="https://mantine.dev/" target="_blank" rel="noreferrer">Mantine</a></td><td>Very productive full component library with many hooks and ready-made controls.</td><td>More of a replacement design system than a primitive layer; likely too opinionated for <code>@soma/ui</code>.</td></tr><tr><td><a href="https://chakra-ui.com/docs/components/concepts/overview" target="_blank" rel="noreferrer">Chakra UI</a></td><td>Complete component inventory and strong composability story.</td><td>Its styling/runtime model is a larger departure from Tailwind-first desktop UI.</td></tr></tbody></table><h2 id="vitepress-compatibility" tabindex="-1">VitePress Compatibility <a class="header-anchor" href="#vitepress-compatibility" aria-label="Permalink to &quot;VitePress Compatibility&quot;">​</a></h2><p>Do not add Chakra UI directly to the VitePress docs theme. Chakra UI is a React component library, while VitePress is Vue-powered. We can still document Chakra UI here as a candidate for the desktop app, but using it inside the docs site would require a React island or iframe bridge and would add framework complexity to a content-first site.</p><p>If the docs need richer interactive examples, prefer one of these:</p><ol><li>Keep the VitePress shell Vue-native and link to Storybook examples under <code>/storybook</code>.</li><li>Build small docs-only Vue components for simple interactivity.</li><li>Embed a React example as an isolated iframe only when it demonstrates real <code>@soma/ui</code> behavior.</li></ol><h2 id="provisional-direction" tabindex="-1">Provisional Direction <a class="header-anchor" href="#provisional-direction" aria-label="Permalink to &quot;Provisional Direction&quot;">​</a></h2><p>Prototype Base UI inside @soma/ui first. If it feels too immature or thin for complex accessibility cases, compare the same component against React Aria Components. Avoid a wholesale framework migration until one vertical slice proves better behavior than the current DaisyUI-based implementation.</p>',18)])])}const u=a(r,[["render",n]]);export{h as __pageData,u as default};
